mapper.select:
SELECT id, ledger_no AS ledgerNo, settlement_id AS settlementId, account_type AS accountType,
       account_id AS accountId, subject, direction, amount, env_flag AS envFlag, created_at AS createdAt
FROM t_ledger WHERE deleted_at IS NULL
AND account_type = #{accountType}
AND account_id = #{accountId}
AND settlement_id = #{settlementId}
ORDER BY id DESC LIMIT 0, 200
